function connect(root) {
    if (!root) {
        return null;
    }
    const q = [
        root
    ];
    while(q.length){
        const nq = [];
        let p = null;
        for (const node of q){
            if (p) {
                p.next = node;
            }
            p = node;
            const { left, right } = node;
            left && nq.push(left);
            right && nq.push(right);
        }
        q.splice(0, q.length, ...nq);
    }
    return root;
}

