        board[i][j] = '.';
        for(let k = 0; k < 4; ++k){
            dfs(i + dirs[k], j + dirs[k + 1]);
        }
    };
    for(let i = 0; i < m; ++i){
        dfs(i, 0);
        dfs(i, n - 1);
    }
    for(let j = 0; j < n; ++j){
        dfs(0, j);
        dfs(m - 1, j);
    }
    for(let i = 0; i < m; ++i){
        for(let j = 0; j < n; ++j){
            if (board[i][j] === '.') {
                board[i][j] = 'O';
            } else if (board[i][j] === 'O') {
                board[i][j] = 'X';
            }
        }
    }
}

