var wordBreak = function(s, wordDict) {
    const words = new Set(wordDict), memo = new Map();
    function sentences(i) {
        if (i === s.length) return [""];
        if (memo.has(i)) return memo.get(i);
        const result = [];
        for (let end = i + 1; end <= s.length; end++) {
            const word = s.slice(i, end);
            if (!words.has(word)) continue;
            for (const tail of sentences(end)) result.push(word + (tail ? " " + tail : ""));
        }
        memo.set(i, result);
        return result;
    }
    return sentences(0);
};

