function rob(nums) {
    const n = nums.length;
    if (n === 1) {
        return nums[0];
    }
    const robRange = (l, r)=>{
        let [f, g] = [
            0,
            0
        ];
        for(; l <= r; ++l){
            [f, g] = [
                Math.max(f, g),
                f + nums[l]
            ];
        }
        return Math.max(f, g);
    };
    return Math.max(robRange(0, n - 2), robRange(1, n - 1));
}

