function findKthLargest(nums, k) {
    const n = nums.length;
    k = n - k;
    const quickSort = (l, r)=>{
        if (l === r) {
            return nums[l];
        }
        let [i, j] = [
            l - 1,
            r + 1
        ];
        const x = nums[l + r >> 1];
        while(i < j){
            while(nums[++i] < x);
            while(nums[--j] > x);
            if (i < j) {
                [nums[i], nums[j]] = [
                    nums[j],
                    nums[i]
                ];
            }
        }
        if (j < k) {
            return quickSort(j + 1, r);
        }
        return quickSort(l, j);
    };
    return quickSort(0, n - 1);
}

