// Source: https://github.com/doocs/leetcode/blob/88c8c2c29f19c186d7cc05c9db17245d9ae3df43/solution/0200-0299/0221.Maximal%20Square/Solution.py

var maximalSquare = function(matrix) {
    if (!matrix.length || !matrix[0].length) return 0;
    const dp = Array(matrix[0].length + 1).fill(0);
    let best = 0;
    for (const row of matrix) {
        let diagonal = 0;
        for (let j = 1; j <= row.length; j++) {
            const above = dp[j];
            dp[j] = row[j - 1] === "1" ? 1 + Math.min(dp[j], dp[j - 1], diagonal) : 0;
            best = Math.max(best, dp[j]);
            diagonal = above;
        }
    }
    return best * best;
};

