var majorityElement = function(nums) {
    let first, second, a = 0, b = 0;
    for (const x of nums) {
        if (x === first) a++;
        else if (x === second) b++;
        else if (a === 0) { first = x; a = 1; }
        else if (b === 0) { second = x; b = 1; }
        else { a--; b--; }
    }
    a = 0; b = 0;
    for (const x of nums) {
        if (x === first) a++;
        else if (x === second) b++;
    }
    const result = [];
    if (a > nums.length / 3) result.push(first);
    if (b > nums.length / 3) result.push(second);
    return result;
};

