function topKFrequent(nums, k) {
    const cnt = new Map();
    for (const x of nums){
        cnt.set(x, (cnt.get(x) ?? 0) + 1);
    }
    const pq = new PriorityQueue((a, b)=>a[1] - b[1]);
    for (const [x, c] of cnt){
        pq.enqueue([
            x,
            c
        ]);
        if (pq.size() > k) {
            pq.dequeue();
        }
    }
    return pq.toArray().map((x)=>x[0]);
}

