// Recall · CC-BY-SA-4.0
// Source: https://github.com/doocs/leetcode/blob/88c8c2c29f19c186d7cc05c9db17245d9ae3df43/solution/0300-0399/0373.Find%20K%20Pairs%20with%20Smallest%20Sums/Solution.py

var kSmallestPairs = function(nums1, nums2, k) {
    const heap = [];
    const less = (a, b) => a[0] < b[0];
    function push(value) {
        heap.push(value);
        for (let i = heap.length - 1; i > 0;) {
            const p = (i - 1) >> 1;
            if (!less(heap[i], heap[p])) break;
            [heap[i], heap[p]] = [heap[p], heap[i]]; i = p;
        }
    }
    function pop() {
        const top = heap[0], last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            for (let i = 0;;) {
                let j = i, left = 2 * i + 1, right = left + 1;
                if (left < heap.length && less(heap[left], heap[j])) j = left;
                if (right < heap.length && less(heap[right], heap[j])) j = right;
                if (j === i) break;
                [heap[i], heap[j]] = [heap[j], heap[i]]; i = j;
            }
        }
        return top;
    }
    if (!nums1.length || !nums2.length || k <= 0) return [];
    for (let i = 0; i < Math.min(nums1.length, k); i++) push([nums1[i] + nums2[0], i, 0]);
    const result = [];
    while (heap.length && result.length < k) {
        const [, i, j] = pop();
        result.push([nums1[i], nums2[j]]);
        if (j + 1 < nums2.length) push([nums1[i] + nums2[j + 1], i, j + 1]);
    }
    return result;
};

