var construct = function(grid) {
    function build(r, c, size) {
        if (size === 1) return new Node(Boolean(grid[r][c]), true, null, null, null, null);
        const h = size / 2;
        const tl = build(r, c, h), tr = build(r, c + h, h);
        const bl = build(r + h, c, h), br = build(r + h, c + h, h);
        if ([tl, tr, bl, br].every(x => x.isLeaf && x.val === tl.val))
            return new Node(tl.val, true, null, null, null, null);
        return new Node(false, false, tl, tr, bl, br);
    }
    return build(0, 0, grid.length);
};

