var compress = function(chars) {
    let read = 0, write = 0;
    while (read < chars.length) {
        const ch = chars[read];
        let end = read + 1;
        while (end < chars.length && chars[end] === ch) end++;
        chars[write++] = ch;
        const count = end - read;
        if (count > 1) for (const digit of String(count)) chars[write++] = digit;
        read = end;
    }
    return write;
};

