    while(qr.length > 0 && qd.length > 0){
        const r = qr.shift();
        const d = qd.shift();
        if (r < d) {
            qr.push(r + n);
        } else {
            qd.push(d + n);
        }
    }
    return qr.length > 0 ? 'Radiant' : 'Dire';
}

