function maxAreaOfIsland(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const dirs = [
        -1,
        0,
        1,
        0,
        -1
    ];
    const dfs = (i, j)=>{
        if (grid[i][j] === 0) {
            return 0;
        }
        let ans = 1;
        grid[i][j] = 0;
        for(let k = 0; k < 4; ++k){
            const [x, y] = [
                i + dirs[k],
                j + dirs[k + 1]
            ];
            if (x >= 0 && x < m && y >= 0 && y < n) {
                ans += dfs(x, y);
            }
        }
        return ans;
    };
    let ans = 0;
    for(let i = 0; i < m; ++i){
        for(let j = 0; j < n; ++j){
            ans = Math.max(ans, dfs(i, j));
        }
    }
    return ans;
}

