function numTilings(n) {
    const mod = 1_000_000_007;
    let f = [
        1,
        0,
        0,
        0
    ];
    for(let i = 1; i <= n; ++i){
        const g = Array(4);
        g[0] = (f[0] + f[1] + f[2] + f[3]) % mod;
        g[1] = (f[2] + f[3]) % mod;
        g[2] = (f[1] + f[3]) % mod;
        g[3] = f[0] % mod;
        f = g;
    }
    return f[0];
}

