function stoneGameII(piles) {
    const n = piles.length;
    const f = Array.from({
        length: n
    }, (_)=>new Array(n + 1).fill(0));
    const s = new Array(n + 1).fill(0);
    for(let i = 0; i < n; ++i){
        s[i + 1] = s[i] + piles[i];
    }
    const dfs = (i, m)=>{
        if (m * 2 >= n - i) {
            return s[n] - s[i];
        }
        if (f[i][m]) {
            return f[i][m];
        }
        let res = 0;
        for(let x = 1; x <= m * 2; ++x){
            res = Math.max(res, s[n] - s[i] - dfs(i + x, Math.max(m, x)));
        }
        return f[i][m] = res;
    };
    return dfs(0, 1);
}

