var longestZigZag = function(root) {
    if (!root) return 0;
    let best = 0;
    const stack = [[root, 0, 0]];
    while (stack.length) {
        const [node, leftLength, rightLength] = stack.pop();
        best = Math.max(best, leftLength, rightLength);
        if (node.left) stack.push([node.left, rightLength + 1, 0]);
        if (node.right) stack.push([node.right, 0, leftLength + 1]);
    }
    return best;
};

