var findCriticalAndPseudoCriticalEdges = function(n, edges) {
    const sorted = edges.map((e, i) => [...e, i]).sort((a, b) => a[2] - b[2]);
    function mst(skip = -1, force = null) {
        const parent = Array.from({length: n}, (_, i) => i), size = Array(n).fill(1);
        function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
        function union(a, b) {
            a = find(a); b = find(b); if (a === b) return false;
            if (size[a] < size[b]) [a, b] = [b, a];
            parent[b] = a; size[a] += size[b]; return true;
        }
        let cost = 0, used = 0;
        if (force && union(force[0], force[1])) { cost += force[2]; used++; }
        for (const [a, b, w, id] of sorted) {
            if (id !== skip && union(a, b)) { cost += w; used++; }
        }
        return used === n - 1 ? cost : Infinity;
    }
    const baseline = mst(), critical = [], pseudo = [];
    for (const e of sorted) {
        if (mst(e[3]) > baseline) critical.push(e[3]);
        else if (mst(-1, e) === baseline) pseudo.push(e[3]);
    }
    return [critical, pseudo];
};

