var canTraverseAllPairs = function(nums) {
    const n = nums.length;
    if (n === 1) return true;
    if (nums.includes(1)) return false;
    const parent = Array.from({length: n}, (_, i) => i), size = Array(n).fill(1), owner = new Map();
    function find(x) { while (x !== parent[x]) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    function union(a, b) {
        a = find(a); b = find(b); if (a === b) return;
        if (size[a] < size[b]) [a, b] = [b, a];
        parent[b] = a; size[a] += size[b];
    }
    function connect(factor, i) {
        if (owner.has(factor)) union(i, owner.get(factor)); else owner.set(factor, i);
    }
    nums.forEach((value, i) => {
        let x = value;
        for (let f = 2; f * f <= x; f++) if (x % f === 0) {
            connect(f, i);
            while (x % f === 0) x /= f;
        }
        if (x > 1) connect(x, i);
    });
    return size[find(0)] === n;
};

