function insertGreatestCommonDivisors(head) {
    for(let pre = head, cur = head.next; cur; cur = cur.next){
        const x = gcd(pre.val, cur.val);
        pre.next = new ListNode(x, cur);
        pre = cur;
    }
    return head;
}
function gcd(a, b) {
    if (b === 0) {
        return a;
    }
    return gcd(b, a % b);
}

